<script setup>
import {watch,onActivated,onDeactivated,onUnmounted} from 'vue';
import {state,api,can,scope} from '../lib/workspace';
import {createSpedGenerator} from '../lib/sped-generator.js';
const reasons={NOT_BOOKED:'Documento ainda não escriturado',MODEL_OR_DIRECTION_NOT_COVERED:'Modelo ou direção fora do recorte de NFC-e próprias de saída',CANCELLATION_NOT_COVERED:'Cancelamento fora do recorte',NON_ACTIVE_SITUATION_NOT_COVERED:'Situação fiscal não ativa fora do recorte',OWN_ISSUANCE_NOT_ESTABLISHED:'Emissão própria não comprovada pela origem'};
const c=createSpedGenerator({state,api,can,scope}),m=c.m;
watch(()=>[state.companyId,state.period,state.session?.user?.id,JSON.stringify(state.session?.permissions||{})],c.reset,{flush:'sync'});
watch(()=>[m.profile,m.activity,m.purpose,m.consolidate,m.segment],c.invalidate,{flush:'sync'});
onActivated(c.activate);onDeactivated(c.deactivate);onUnmounted(c.deactivate);
function traceDownload(){if(!c.downloadable())return;const {content_base64,...trace}=m.result;const url=URL.createObjectURL(new Blob([JSON.stringify(trace,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='rastreabilidade-'+m.result.filename+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function download(){const file=c.file();if(!file)return;const url=URL.createObjectURL(new Blob([file.bytes],{type:'text/plain;charset=iso-8859-1'}));const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><div class="view sped-generator-view"><header class="view-heading"><div><div class="eyebrow">FERRAMENTAS FISCAIS</div><h1>Gerador SPED</h1><p>Geração a partir da escrituração da empresa e competência ativas.</p></div></header>
<div class="panel"><h2>Bloco C de NFC-e próprias</h2><p>Recorte parcial: não é uma EFD completa, não foi validado no PVA e não transmite obrigações. Outros modelos, apuração e demais blocos não estão incluídos. ECD, ECF e EFD-Contribuições continuam em preparação, sem geradores completos nesta tela.</p></div>
<form class="panel" @submit.prevent="c.generate"><div class="form-grid three"><label>Perfil da EFD<select v-model="m.profile" required><option value="">Selecione</option><option>A</option><option>B</option><option>C</option></select></label><label>Atividade<select v-model="m.activity" required><option value="">Selecione</option><option value="0">Industrial ou equiparado</option><option value="1">Outras atividades</option></select></label><label>Finalidade<select v-model="m.purpose" required><option value="">Selecione</option><option value="0">Original</option><option value="1">Substituta</option></select></label></div>
<label><input type="checkbox" v-model="m.consolidate"/> Consolidar NFC-e por dia e série apenas no arquivo gerado</label><label v-if="m.consolidate"><input type="checkbox" v-model="m.segment"/> Separar grupos quando houver intervalo na numeração</label><p v-if="m.consolidate">Consolidação operacional, não oficial: preserva os documentos individuais e não realiza lançamentos. A chave do grupo é a da primeira nota, não uma nova nota fiscal.</p>
<div class="actions"><button class="button primary" :disabled="m.busy||!c.permitted()">{{m.busy?'Gerando…':'Gerar recorte'}}</button><button v-if="m.busy" type="button" class="button" @click="c.cancel">Cancelar espera</button></div><p v-if="!c.permitted()">Necessário acesso de leitura e exportação aos documentos fiscais.</p><p v-if="m.error" role="alert">{{m.error}}</p></form>
<section v-if="m.result" class="panel" aria-label="Resultado da geração"><h2>Arquivo parcial gerado</h2><p>{{m.result.summary.exported_documents}} documentos incluídos; {{m.result.summary.skipped_documents}} não incluídos. {{m.result.consolidated?'Consolidação aplicada.':'Documentos individuais.'}}</p><div class="actions"><button class="button" :disabled="!c.downloadable()" @click="download">Baixar TXT parcial</button><button class="button" :disabled="!c.downloadable()" @click="traceDownload">Baixar rastreabilidade JSON</button></div><p>O download não altera a escrituração. Importar um bloco no PVA pode substituir as informações desse bloco; confira todos os avisos e o arquivo antes de utilizá-lo.</p>
<details open><summary>Avisos de conferência ({{m.result.warnings.length}})</summary><ul><li v-for="(w,i) in m.result.warnings" :key="i">{{w.message}} <span v-if="w.record||w.field">{{w.record}} {{w.field}}</span> <span v-if="w.count>1">({{w.count}} ocorrências)</span></li></ul></details>
<details v-if="m.result.skipped.length"><summary>Documentos não incluídos</summary><div class="table-scroll"><table><thead><tr><th>Documento</th><th>Motivo</th></tr></thead><tbody><tr v-for="d in m.result.skipped" :key="d.document_id"><td>{{d.document_id}}</td><td>{{reasons[d.reason]||d.reason}}</td></tr></tbody></table></div></details><details><summary>Rastreabilidade</summary><p>SHA-256 do arquivo: {{m.result.result_sha256}}</p><p>Referências individuais e versões de origem permanecem no resultado da API, sem modificar os documentos.</p></details></section></div></template>
<style scoped>
.sped-generator-view .panel{padding:1.25rem;margin-bottom:1rem}.sped-generator-view h2{font-size:1.05rem;margin:0 0 .65rem}.sped-generator-view .panel p{margin:.55rem 0;line-height:1.55}.sped-generator-view details{margin-top:1rem}.sped-generator-view summary{cursor:pointer;font-weight:600}.sped-generator-view li{margin:.35rem 0}.sped-generator-view .actions{flex-wrap:wrap;gap:.5rem;margin-top:1rem}

.sped-generator-view p,.sped-generator-view li{overflow-wrap:anywhere}.sped-generator-view form>label{display:block;margin:.8rem 0}.sped-generator-view input[type=checkbox]{width:auto;margin-right:.4rem}
</style>
